import{_ as a,V as d,W as t,Z as e,$ as n,a0 as c,Y as r,F as i,a1 as l}from"./framework-b1bd8911.js";const s={},u=r('<h1 id="date-plugin-农历工具" tabindex="-1"><a class="header-anchor" href="#date-plugin-农历工具" aria-hidden="true">#</a> date-plugin 农历工具</h1><blockquote><p>date-plugin 是 QuickMedia 多媒体工具箱中的公历/农历转换插件，纯 Java 实现、零第三方依赖，核心是两个工具类：<code>ChineseDateTool</code> 负责公历与农历之间的相互转换，<code>ChineseDateExtendTool</code> 在转换的基础上封装了干支纪年、生肖风格的大写月日、十二时辰等中文输出，几行代码就能拿到 <code>己亥年伍月壹捌 辰时</code> 这种生辰八字风格的日期描述。</p></blockquote><h2 id="能力清单" tabindex="-1"><a class="header-anchor" href="#能力清单" aria-hidden="true">#</a> 能力清单</h2><ul><li><strong>公历转农历</strong>：<code>ChineseDateTool.solarToLunar(Solar)</code>，输出农历年、月、日，并带闰月标记 <code>isleap</code></li><li><strong>农历转公历</strong>：<code>ChineseDateTool.lunarToSolar(Lunar)</code>，与上面的转换可逆</li><li><strong>干支纪年</strong>：<code>lunarYearToGanZhi</code>，输出如 <code>己亥年</code></li><li><strong>农历月/日中文输出</strong>：<code>lunarMonthToChinese</code>、<code>lunarDayToChinese</code>，输出如 <code>伍月</code>、<code>壹捌</code>，闰月自动加前缀</li><li><strong>十二时辰</strong>：<code>hourToChinese</code>，24 小时制转 <code>辰时</code> 这种传统时辰说法</li><li><strong>开箱即用的组合方法</strong>：<code>getNowLunarDate()</code>（当前时间转生辰八字风格）、<code>getLunarDateByTimestamp()</code>（毫秒时间戳转农历描述）、<code>parseLunar()</code>（Lunar 对象转字符串）</li></ul><h2 id="相关文章" tabindex="-1"><a class="header-anchor" href="#相关文章" aria-hidden="true">#</a> 相关文章</h2>',5);function h(g,_){const o=i("RouterLink");return d(),t("div",null,[u,e("ul",null,[e("li",null,[n(o,{to:"/git/quick-media/date/01.%E5%85%AC%E5%8E%86%E4%B8%8E%E5%86%9C%E5%8E%86%E4%BA%92%E8%BD%AC.html"},{default:c(()=>[l("公历与农历互转")]),_:1})])])])}const m=a(s,[["render",h],["__file","index.html.vue"]]);export{m as default};
